<script setup lang="ts">
import {computed,ref,watch} from 'vue'
import {useRoute,useRouter} from 'vue-router'
import {VAlert,VSelect,VSwitch,VSnackbar} from 'vuetify/components'
import {adminApi,adminError} from './api'
import {entityFields,entityNames,valueOf,setValue,recordTitle,priceLabel} from './entitySchema'
import {clone,languages,publicPaths,type Language} from './contentSchema'
import {languagePath} from '../i18n/urls'
import {useUnsaved} from './useUnsaved'
import LanguageTabs from './LanguageTabs.vue'
import FriendlyField from './FriendlyField.vue'
import ImageField from './ImageField.vue'
import SaveBar from './SaveBar.vue'
import SectionPreview from './SectionPreview.vue'
const route=useRoute(),router=useRouter()
const kind=computed(()=>route.meta.adminArea==='seo'?'pages':String(route.meta.adminArea))
const model=ref<any>({}),original=ref<any>({}),language=ref<Language>('ru'),loading=ref(true),busy=ref(false),error=ref(''),errors=ref<Record<string,string>>({}),snackbar=ref(false),services=ref<any[]>([]),options=ref<any[]>([])
const fields=computed(()=>entityFields[kind.value]||[]),groups=computed(()=>[...new Set(fields.value.map(f=>f.group))]),dirty=computed(()=>JSON.stringify(model.value)!==JSON.stringify(original.value)),isNew=computed(()=>route.params.id==='new')
useUnsaved(dirty)
const complete=computed(()=>Object.fromEntries(languages.map(lang=>[lang,fields.value.filter(f=>f.required).every(f=>valueOf(model.value,f.key,lang,kind.value).trim())])) as Record<string,boolean>)
const previewFields=computed(()=>fields.value.filter(f=>!['Дополнительные тексты','Поисковая выдача'].includes(f.group)&&(kind.value!=='reviews'||f.key==='full_text')))
const values=computed(()=>Object.fromEntries(fields.value.map(f=>[f.key,valueOf(model.value,f.key,language.value,kind.value)])))
const selectedCodes=computed({get:()=>model.value.options?.map((o:any)=>o.code)||[],set:(codes:string[])=>{model.value.options=codes.map(code=>({code}))}})
const asset=computed(()=>model.value.assets?.find((a:any)=>a.language===language.value)?.media)
function chooseAsset(media:any){model.value.assets=(model.value.assets||[]).filter((a:any)=>a.language!==language.value);model.value.assets.push({language:language.value,media_id:media.id,media})}
const money=computed({get:()=>model.value.price_input??(model.value.price==null?'':String(model.value.price/100)),set:(v:string)=>{model.value.price_input=v; if(/^\d+(?:[.,]\d{0,2})?$/.test(v)){const [w,f='']=v.replace(',','.').split('.');model.value.price=Number(w)*100+Number(f.padEnd(2,'0'))}else if(v==='')model.value.price=null}})
const date=computed({get:()=>model.value.issued_at?.slice(0,10)||'',set:(v:string)=>{model.value.issued_at=v?v+'T00:00:00Z':null}})
const localizedURL=(lang:Language)=>(import.meta.env.VITE_SITE_URL||window.location.origin).replace(/\/$/,'')+languagePath(publicPaths[model.value.key]||'/',lang)
const canonical=computed(()=>localizedURL(language.value))
async function all(kind:string){let page=1,result:any[]=[];for(;;){const {data}=await adminApi.get('/entities/'+kind,{params:{page,limit:100}});result.push(...data.items);if(result.length>=data.total) return result;page++}}
let generation=0
async function load(){
 const g=++generation;loading.value=true;error.value='';errors.value={}
 try{
  const k=kind.value,newRecord=isNew.value
  const record=newRecord?{is_active:k!=='reviews',sort_order:0,translations:[],assets:[],options:[],service_id:Number(route.query.service)||null,is_addon:false,price:null}:(await adminApi.get('/entities/'+k+'/'+(k==='settings'?1:route.params.id))).data
  const [serviceRows,optionRows]=await Promise.all([['directions','options'].includes(k)?all('services'):[],['directions','services'].includes(k)?all('options'):[]])
  if(g!==generation)return
  model.value=record;original.value=clone(record);services.value=serviceRows;options.value=k==='services'?optionRows.filter((o:any)=>o.service_id===record.id):optionRows
 }catch(e){if(g===generation)error.value=adminError(e)}finally{if(g===generation)loading.value=false}
}
watch(()=>route.path,load,{immediate:true})
function cancel(){if(window.confirm('Отменить несохранённые изменения?')){model.value=clone(original.value);errors.value={};error.value=''}}
async function save(){error.value='';errors.value={};for(const f of fields.value.filter(f=>f.required))if(!valueOf(model.value,f.key,'ru',kind.value).trim())errors.value[f.key]='Заполните это поле на русском языке.';if(['options','directions'].includes(kind.value)&&!model.value.service_id)errors.value.service_id='Выберите услугу.';
if(kind.value==='settings'){if(!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(model.value.email||''))errors.value.email='Проверьте адрес email.';if(!/^[1-9][0-9]{6,14}$/.test(model.value.whatsapp_phone||''))errors.value.whatsapp_phone='Укажите международный номер: только цифры.';if(model.value.telegram_url&&!/^https:\/\/t\.me\/[a-zA-Z][a-zA-Z0-9_]{3,31}\/?$/.test(model.value.telegram_url))errors.value.telegram_url='Используйте ссылку вида https://t.me/username.'}
if(Object.keys(errors.value).length){language.value='ru';return}if(kind.value==='options'&&model.value.price_input!==undefined&&!/^\d{1,7}(?:[.,]\d{1,2})?$/.test(model.value.price_input)&&model.value.price_input!==''){errors.value.price='Укажите цену, например 50 или 50,50.';return}if(kind.value==='reviews'&&model.value.is_active&&!model.value.publication_consent){errors.value.publication_consent='Для публикации отзыва нужно согласие автора.';return}busy.value=true;try{const data=clone(model.value);delete data.price_input;if(kind.value==='certificates')data.assets=(data.assets||[]).map((a:any)=>({language:a.language,media_id:a.media_id}));if(isNew.value){if(kind.value==='services'||kind.value==='directions')data.slug='material-'+crypto.randomUUID();if(kind.value==='options')data.code='variant-'+crypto.randomUUID();const response=await adminApi.post('/entities/'+kind.value,data);const id=kind.value==='options'?response.data.code:response.data.id;original.value=clone(model.value);await router.replace('/admin/'+kind.value+'/'+id)}else{const id=kind.value==='settings'?1:route.params.id;await adminApi.put('/entities/'+kind.value+'/'+id,data);const saved=(await adminApi.get('/entities/'+kind.value+'/'+id)).data;model.value=saved;original.value=clone(saved)}snackbar.value=true}catch(e){error.value=adminError(e)}finally{busy.value=false}}
</script>
<template><p v-if="loading" role="status">Загружаем редактор…</p><template v-else><div class="admin-page-heading"><div><RouterLink v-if="kind!=='settings'" :to="'/admin/'+(kind==='pages'?'seo':kind==='options'?'services':kind)" class="admin-back"><v-icon icon="mdi-arrow-left" size="18"/> {{entityNames[kind==='options'?'services':kind]}}</RouterLink><p class="admin-kicker">{{isNew?'Новый материал':'Редактор'}}</p><h1>{{recordTitle(model,kind)}}</h1></div></div><v-alert v-if="error&&!dirty" type="error">{{error}}</v-alert><SaveBar :dirty="dirty" :busy="busy" :error="error" @save="save" @cancel="cancel"/><div class="admin-editor-layout"><div class="editor-fields"><LanguageTabs v-model="language" :complete="complete"/><section v-if="kind==='settings'" class="editor-group"><h2>Контакты и имя</h2><p class="admin-muted">Эти данные одинаковы для всех языков сайта.</p><v-text-field v-model="model.expert_name" label="Имя специалиста"/><v-text-field v-model="model.phone" label="Телефон"/><v-text-field v-model="model.email" label="Email" type="email" :error-messages="errors.email"/><v-text-field v-model="model.whatsapp_phone" label="Номер WhatsApp" :error-messages="errors.whatsapp_phone" hint="Цифры с кодом страны, без пробелов и знака +" persistent-hint/><v-text-field v-model="model.telegram_url" label="Ссылка на Telegram" :error-messages="errors.telegram_url"/></section><section v-if="kind==='reviews'" class="editor-group"><h2>Автор и публикация</h2><v-text-field v-model="model.author_display_name" label="Имя автора (необязательно)"/><v-checkbox v-model="model.publication_consent" label="Есть согласие автора на публикацию" :error-messages="errors.publication_consent"/><v-switch v-model="model.is_featured" label="Показывать в избранных на главной" color="primary"/><v-text-field v-if="model.is_featured" v-model.number="model.home_sort_order" type="number" label="Порядок на главной"/></section><template v-for="group in groups" :key="group"><component :is="group==='Дополнительные тексты'?'details':'section'" class="editor-group"><component :is="group==='Дополнительные тексты'?'summary':'h2'">{{group}}</component><p v-if="group==='Дополнительные тексты'" class="admin-muted">Эти тексты сохранены в контенте, но соответствующие блоки скрыты на сайте.</p><FriendlyField v-for="field in fields.filter(f=>f.group===group)" :key="field.key+'-'+language" :model-value="valueOf(model,field.key,language,kind)" @update:model-value="setValue(model,field.key,language,kind,$event)" :label="field.label" :rows="field.rows" :help="field.help" :required="field.required&&language==='ru'" :error="language==='ru'?errors[field.key]:''" :counter="group==='Поисковая выдача'"/></component></template><section v-if="['services','directions','options'].includes(kind)" class="editor-group"><ImageField v-model="model.image"/></section><section v-if="kind==='certificates'" class="editor-group"><h2>Документ</h2><v-text-field v-model="model.issuer" label="Организация, выдавшая сертификат"/><v-text-field v-model="model.year" inputmode="numeric" label="Год обучения"/><v-text-field v-model="date" type="date" label="Дата выдачи (необязательно)"/><div class="certificate-languages"><button v-for="lang in languages" :key="lang" type="button" :class="{selected:language===lang}" @click="language=lang"><strong>{{lang.toUpperCase()}}</strong><img v-if="model.assets?.find((a:any)=>a.language===lang)?.media?.storage_path" :src="model.assets.find((a:any)=>a.language===lang).media.storage_path" alt=""/><span v-else>Версия {{lang.toUpperCase()}} не загружена</span></button></div><ImageField :model-value="asset?.storage_path" @selected="chooseAsset" :label="'Сертификат — '+language.toUpperCase()" missing="Для этого языка документ не выбран. На сайте будет использован EN, затем RU."/></section><section v-if="kind==='options'||kind==='directions'" class="editor-group"><h2>Связь с услугой</h2><v-select v-model="model.service_id" label="Услуга" :error-messages="errors.service_id" :disabled="kind==='options'&&!isNew" :items="services.map(s=>({title:s.title_ru,value:s.id}))" @update:model-value="selectedCodes=[]"/><v-select v-if="kind==='directions'" v-model="selectedCodes" label="Доступные форматы" multiple chips :items="options.filter(o=>o.service_id===model.service_id&&!o.is_addon).map(o=>({title:o.title_ru,value:o.code}))"/><template v-if="kind==='options'"><v-text-field v-model="money" label="Цена, €" :error-messages="errors.price" inputmode="decimal" hint="0 — бесплатно; пустое поле — цена не определена." persistent-hint/><v-switch v-model="model.is_addon" label="Дополнение к основному разбору" :disabled="!isNew" color="primary"/></template></section><section v-if="kind==='services'" class="editor-group"><h2>Варианты и дополнения</h2><p class="admin-muted">Цены задаются для каждого варианта отдельно.</p><p v-if="isNew">Сначала сохраните услугу, затем добавьте варианты.</p><template v-else><RouterLink v-for="option in options" :key="option.code" :to="'/admin/options/'+option.code" class="editor-related"><span>{{option.title_ru}}<small>{{option.is_addon?'Дополнение':'Основной вариант'}} · {{priceLabel(option.price)}}</small></span><v-icon icon="mdi-arrow-top-right"/></RouterLink><v-btn :to="'/admin/options/new?service='+model.id" variant="outlined">Добавить вариант</v-btn></template></section><details v-if="!['pages','settings'].includes(kind)" class="editor-group"><summary>Публикация и порядок</summary><v-switch v-model="model.is_active" label="Показывать на сайте" color="primary"/><v-text-field v-model.number="model.sort_order" label="Порядок в списке" type="number"/></details><details v-if="kind==='pages'" class="editor-group"><summary>Адреса и языковые версии</summary><p class="admin-muted">Формируются автоматически. Изменение текста не меняет адрес страницы.</p><p class="admin-url">Canonical: {{canonical}}</p><p v-for="lang in languages" :key="lang" class="admin-url">{{lang.toUpperCase()}}: {{localizedURL(lang)}}</p></details></div><aside v-if="kind==='pages'" class="seo-preview" aria-hidden="true" inert><p class="admin-kicker">Предпросмотр в Google</p><div class="seo-result"><small>{{canonical}}</small><h2>{{values.meta_title||'Заголовок страницы'}}</h2><p>{{values.meta_description||'Описание страницы появится здесь.'}}</p></div><p class="admin-muted">Поисковая система может сократить или изменить текст сниппета.</p></aside><aside v-else-if="kind==='settings'" class="seo-preview" aria-hidden="true" inert><p class="admin-kicker">Контактная карточка</p><h2>{{model.expert_name}}</h2><p>{{values.professional_title}}</p><p>{{model.phone}}</p><p>{{model.email}}</p><p>WhatsApp: {{model.whatsapp_phone}}</p><p class="admin-url">{{model.telegram_url}}</p></aside><SectionPreview v-else :fields="previewFields" :values="values" :image="kind==='certificates'?asset?.storage_path:model.image" :type="model.image?'text-image':'text'"/></div><v-snackbar v-model="snackbar" color="success" timeout="3000">Изменения сохранены</v-snackbar></template></template>
